const raw = $('Recibir Datos').first().json;
const d = raw.fecha != null ? raw : JSON.parse(raw.query || '{}');
const valido = v => v != null && String(v).trim() !== '' && String(v) !== 'undefined' && String(v) !== 'null';
if (!valido(d.fecha)) return [{ json: { resultado: 'ERROR: no se recibió una fecha válida. Indicá la fecha en formato YYYY-MM-DD.' } }];
const fecha = String(d.fecha).trim();

const [year, month, day] = fecha.split('-').map(Number);
const dateObj = new Date(year, month - 1, day);
const dow = dateObj.getDay();

if (dow === 0) {
  return [{ json: { resultado: 'El consultorio no atiende los domingos. Podés consultar de lunes a sábado.' } }];
}

const endMin = dow === 6 ? 780 : 1260;
const allSlots = [];
for (let m = 480; m + 45 <= endMin; m += 45) {
  allSlots.push(String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'));
}

const busyStates = ['PENDIENTE', 'CONFIRMADO', 'RECORDATORIO_ENVIADO'];
const occupied = $input.all()
  .filter(i => i.json.fecha === fecha && busyStates.includes(i.json.estado_turno))
  .map(i => i.json.hora);

const free = allSlots.filter(s => !occupied.includes(s));

const resultado = free.length === 0
  ? 'No hay turnos disponibles para el ' + fecha + '. ¿Querés que verifique otro día?'
  : 'Los horarios disponibles para el ' + fecha + ' son: ' + free.join(', ') + '. ¿Cuál preferís?';

return [{ json: { resultado } }];
